function showToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=2.2}
function updateHud(){const found=runes.filter(r=>r.found).length;document.getElementById('runeCount').textContent=`${found} / 3`;document.querySelectorAll('.rune-dot').forEach((el,i)=>el.classList.toggle('found',runes[i].found));document.getElementById('healthFill').style.width=`${Math.max(0,player.hp)/player.maxHp*100}%`;document.getElementById('heartText').textContent='♥ '.repeat(Math.max(0,player.hp)).trim()||'♡';document.getElementById('questText').textContent=found===3?'All runes found! Return to the castle gate.':'Recover the three runes hidden in the old forest.';document.getElementById('statusNote').textContent=found===3?'The castle gate is waiting.':player.hp===1?'Careful now, brave fox.':'A little brave, a little wild.'}
function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=35+Math.random()*110;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:2+Math.random()*3,life:.35+Math.random()*.45,color})}}
function beginAttack(){if(!playing||paused||player.attack>0)return;player.attack=.29;player.attackHit=false}
