function endGame(victory){playing=false;gameOver=true;won=victory;overlay.classList.remove('hidden');document.getElementById('overlayEyebrow').textContent=victory?'A legend is born':'A brief rest';document.getElementById('overlayTitle').innerHTML=victory?'Mosskeep is<br>safe again':'The imps<br>got you';document.getElementById('overlayCopy').textContent=victory?'With three moon runes glowing and the castle bells ringing, our fox knight has saved Mosskeep. The forest will remember this little hero.':'The forest imps were too much this time. Take a breath, brave fox — the runes will be waiting.';startBtn.textContent=victory?'Play again →':'Try again →';document.getElementById('overlaySub').textContent=victory?'Quest complete · Fox knight of Mosskeep':'You can do this · Keep moving and use your dash.'}
function startGame(){if(gameOver){runes.forEach(r=>r.found=false);player.x=950;player.y=810;player.hp=3;player.dirX=0;player.dirY=-1;player.attack=0;player.dash=0;player.dashCd=0;player.invuln=0;particles=[];initWorld();updateHud()}gameOver=false;paused=false;playing=true;overlay.classList.add('hidden');startBtn.textContent='Begin your quest →';}
function togglePause(){if(!playing&& !paused)return;paused=!paused;if(paused){overlay.classList.remove('hidden');document.getElementById('overlayEyebrow').textContent='Take a breather';document.getElementById('overlayTitle').innerHTML='Quest<br>paused';document.getElementById('overlayCopy').textContent='The forest can wait. Your runes and progress are safe right here.';startBtn.textContent='Back to the forest →';document.getElementById('overlaySub').textContent='WASD to move · Space to slash · Shift to dash'}else{overlay.classList.add('hidden');playing=true}}
startBtn.addEventListener('click',()=>{if(paused){togglePause();return}startGame()});document.getElementById('pauseBtn').addEventListener('click',togglePause);
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'){togglePause();return}keys.add(e.code);if(e.code==='Space'&&!e.repeat)beginAttack();if((e.code==='ShiftLeft'||e.code==='ShiftRight'||e.code==='Shift')&&!e.repeat)doDash();if((e.code==='Enter'||e.code==='Space')&&!playing&&(!paused||gameOver)){if(gameOver)startGame();else if(!paused)startGame()}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
document.querySelectorAll('[data-key]').forEach(btn=>{const key=btn.dataset.key;const down=e=>{e.preventDefault();btn.setPointerCapture?.(e.pointerId);keys.add(key);if(key==='Space')beginAttack();if(key==='Shift')doDash()};const up=e=>{e.preventDefault();keys.delete(key)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);updateHud();
})();
</script>
</body>
</html>

